DELETE FROM TASK   /* QueryID : com.demo.proworks.task.design.deleteDesign */ 
WHERE   
        TASK_ID     = #{taskId}

mapper.select:
SELECT /* QueryID : com.demo.proworks.task.design.selectListDesign */ taskId, taskName, taskDes, taskStatus, isTest, taskDepth, stgId, ptTaskId, taskSeq, taskSt, taskEt, taskRst, taskRet, taskAsi, taskRate, pjtId, ptTaskName, stgName FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT t.TASK_ID as taskId, t.TASK_NAME as taskName, t.TASK_DES as taskDes, t.TASK_STATUS as taskStatus, t.IS_TEST as isTest, t.TASK_DEPTH as taskDepth, t.STG_ID as stgId, t.PT_TASK_ID as ptTaskId, t.TASK_SEQ as taskSeq, t.TASK_ST as taskSt, t.TASK_ET as taskEt, t.TASK_RST as taskRst, t.TASK_RET as taskRet, t.TASK_ASI as taskAsi, t.TASK_RATE as taskRate, t.PJT_ID as pjtId,
COALESCE(pt.TASK_NAME, t.PT_TASK_NAME) as ptTaskName, s.STG_NAME as stgName FROM TASK t LEFT JOIN TASK pt ON t.PT_TASK_ID = pt.TASK_ID LEFT JOIN STG s ON t.STG_ID = s.STG_ID WHERE t.STG_ID BETWEEN 1 AND 5 AND t.PJT_ID = #{pjtId}
AND t.TASK_NAME like '%${scTaskName}%'
AND t.TASK_STATUS like '%${scTaskStatus}%'
AND t.IS_TEST like '%${scIsTest}%'
AND t.STG_ID like '%${scStgId}%'
) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}

SELECT /* QueryID : com.demo.proworks.task.design.selectListDesign */ taskId, taskName, taskDes, taskStatus, isTest, taskDepth, stgId, ptTaskId, taskSeq, taskSt, taskEt, taskRst, taskRet, taskAsi, taskRate, pjtId, ptTaskName, stgName FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT t.TASK_ID as taskId, t.TASK_NAME as taskName, t.TASK_DES as taskDes, t.TASK_STATUS as taskStatus, t.IS_TEST as isTest, t.TASK_DEPTH as taskDepth, t.STG_ID as stgId, t.PT_TASK_ID as ptTaskId, t.TASK_SEQ as taskSeq, t.TASK_ST as taskSt, t.TASK_ET as taskEt, t.TASK_RST as taskRst, t.TASK_RET as taskRet, t.TASK_ASI as taskAsi, t.TASK_RATE as taskRate, t.PJT_ID as pjtId, pt.TASK_NAME as ptTaskName, s.STG_NAME as stgName FROM TASK t LEFT JOIN TASK pt ON t.PT_TASK_ID = pt.TASK_ID LEFT JOIN STG s ON t.STG_ID = s.STG_ID WHERE t.STG_ID = 6 AND t.PJT_ID = #{pjtId}
AND t.TASK_NAME like '%${scTaskName}%'
AND t.TASK_STATUS like '%${scTaskStatus}%'
AND t.IS_TEST like '%${scIsTest}%'
AND t.STG_ID like '%${scStgId}%'
) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}
